import {
    LayoutDashboard,
    Users,
    UserPlus,
    Receipt,
    ArrowRight,
    Link2,
    Settings,
    ChevronRight,
    IndianRupee,
  } from "lucide-react";

  const mainLinks = [
    { id: "overview", label: "Overview", icon: LayoutDashboard },
    { id: "groups", label: "Groups", icon: Users },
    { id: "friends", label: "Friends", icon: UserPlus },
    { id: "expenses", label: "Expenses", icon: Receipt },
    { id: "settlements", label: "Settlements", icon: ArrowRight, badge: 3 },
  ];

  const quickLinks = [
    { id: "join-group", label: "Join a group", icon: Link2 },
    { id: "settings", label: "Settings", icon: Settings },
  ];

  function NavItem({ item, active, onClick }) {
    const Icon = item.icon;
    return (
      <button
        onClick={() => onClick(item.id)}
        className={`w-full flex items-center gap-4 px-5 py-3.5 rounded-xl text-left font-medium transition-colors ${
          active
            ? "bg-brand/30 text-white"
            : "text-slate-300 hover:bg-white/5 hover:text-white"
        }`}
      >
        <Icon size={20} strokeWidth={1.8} />
        <span className="flex-1">{item.label}</span>
        {item.badge && (
          <span className="w-6 h-6 rounded-full bg-brand text-white text-xs font-semibold flex items-center justify-center">
            {item.badge}
          </span>
        )}
      </button>
    );
  }

  function Sidebar({ activePage, onNavigate }) {
    return (
      <aside className="hidden lg:flex w-72 shrink-0 flex-col bg-ink text-white px-4 py-6 sticky top-0 h-screen">
        {/* Logo */}
        <div className="flex items-center gap-3 px-2 mb-10">
          <div className="w-11 h-11 rounded-xl bg-brand flex items-center justify-center">
            <IndianRupee size={22} />
          </div>
          <span className="text-2xl font-bold tracking-tight">
            fair<span className="text-brand">share</span>
          </span>
        </div>

        {/* Main nav */}
        <p className="px-3 mb-3 font-mono text-[11px] tracking-widest text-slate-500 uppercase">
          Your college circle
        </p>
        <nav className="flex flex-col gap-1.5">
          {mainLinks.map((item) => (
            <NavItem
              key={item.id}
              item={item}
              active={activePage === item.id}
              onClick={onNavigate}
            />
          ))}
        </nav>

        {/* Quick links */}
        <p className="px-3 mt-10 mb-3 font-mono text-[11px] tracking-widest text-slate-500 uppercase">
          Quick links
        </p>
        <nav className="flex flex-col gap-1.5">
          {quickLinks.map((item) => (
            <NavItem
              key={item.id}
              item={item}
              active={activePage === item.id}
              onClick={onNavigate}
            />
          ))}
        </nav>

        {/* Profile card */}
        <button
          onClick={() => onNavigate("profile")}
          className="mt-auto flex items-center gap-3 p-4 rounded-2xl bg-inkSoft hover:bg-white/10 transition-colors text-left"
        >
          <div className="w-11 h-11 rounded-full border-2 border-brand bg-brand/20 flex items-center justify-center text-sm font-semibold">
            KS
          </div>
          <div className="flex-1">
            <p className="font-semibold leading-tight">Krisha Shah</p>
            <p className="text-sm text-slate-400">Gujarat student</p>
          </div>
          <ChevronRight size={18} className="text-slate-400" />
        </button>
      </aside>
    );
  }

  export default Sidebar;
